parameters.jsCode:
// Get the raw text output from the AI Agent
const raw = $json.output ?? '';

// Get the context prepared by "Build AI Context from Airtable"
const ctx = $('Build AI Context from Airtable').item.json;

// Get existing customer data from Airtable, if available
const existing = ctx.existingData || {};


// Try to read JSON from the AI response
function extractJson(text) {
  try {
    return JSON.parse(text);
  } catch (e) {
    // If AI added extra text, try to find only the JSON part
    const match = String(text).match(/\{[\s\S]*\}/);
    if (match) {
      try {
        return JSON.parse(match[0]);
      } catch (e2) {}
    }
  }

  return null;
}


// Convert values like "2.000 €" or "2000" into a number
function toNumber(value) {
  if (value === null || value === undefined || value === '') return 0;

  return Number(
    String(value)
      .replace(/[^\d,.-]/g, '') // remove currency symbols and text
      .replace(',', '.')        // change comma to dot
  ) || 0;
}


// For text fields:
// Use the new AI value first.
// If missing, keep the old Airtable value.
// If both are missing, use fallback.
function textValue(newValue, oldValue, fallback = '') {
  if (newValue !== undefined && newValue !== null && String(newValue).trim() !== '') {
    return String(newValue).trim();
  }

  if (oldValue !== undefined && oldValue !== null && String(oldValue).trim() !== '') {
    return String(oldValue).trim();
  }

  return fallback;
}


// For number fields:
// Use the new AI value first.
// If missing, keep the old Airtable value.
// If both are missing, use fallback.
function numberValue(newValue, oldValue, fallback = 0) {
  const n = toNumber(newValue);
  if (n > 0) return n;

  const o = toNumber(oldValue);
  if (o > 0) return o;

  return fallback;
}


// Parse the AI output
const parsed = extractJson(raw);

// Get leadData from the AI response
const aiLead = parsed?.leadData || {};


// Build final lead data
// Important: this keeps existing Airtable values if AI does not send them again
const leadData = {
  phone: textValue(aiLead.phone, ctx.phone, ''),

  // New fields
  fullName: textValue(aiLead.fullName, existing.fullName, ''),
  email: textValue(aiLead.email, existing.email, ''),

  // Existing fields
  firstName: textValue(aiLead.firstName, existing.firstName, ''),
  nationality: textValue(aiLead.nationality, existing.nationality, ''),
  age: numberValue(aiLead.age, existing.age, 0),
  maritalStatus: textValue(aiLead.maritalStatus, existing.maritalStatus, 'Unknown'),

  // Number of children can be 0, so we handle it separately
  numberChildren:
    aiLead.numberChildren !== undefined &&
    aiLead.numberChildren !== null &&
    String(aiLead.numberChildren).trim() !== ''
      ? toNumber(aiLead.numberChildren)
      : (
          existing.numberChildren !== undefined &&
          existing.numberChildren !== null &&
          String(existing.numberChildren).trim() !== ''
            ? toNumber(existing.numberChildren)
            : 0
        ),

  netSalary: numberValue(aiLead.netSalary, existing.netSalary, 0),
  budget: numberValue(aiLead.budget, existing.budget, 0),
  timeline: textValue(aiLead.timeline, existing.timeline, 'Just exploring'),
  mortgageStatus: textValue(aiLead.mortgageStatus, existing.mortgageStatus, 'Unknown'),
  propertyType: textValue(aiLead.propertyType, existing.propertyType, 'Other'),
  preferredAreas: textValue(aiLead.preferredAreas, existing.preferredAreas, ''),

  // Keep qualifiedLead true if AI says true OR it was already true in Airtable
  qualifiedLead:
    aiLead.qualifiedLead === true ||
    aiLead.qualifiedLead === 'true' ||
    existing.qualifiedLead === true,
};


// These text fields must be filled before the lead is complete
const requiredTextFields = [
  'phone',
  'fullName',
  'firstName',
  'email',
  'nationality',
  'maritalStatus',
  'timeline',
  'mortgageStatus',
  'propertyType',
  'preferredAreas',
];


// Check if all required text fields are filled
const textFieldsComplete = requiredTextFields.every((field) => {
  return String(leadData[field] ?? '').trim() !== '';
});


// Check if important number fields are complete
const numberFieldsComplete =
  leadData.age > 0 &&
  leadData.netSalary > 0 &&
  leadData.budget > 0 &&
  leadData.numberChildren >= 0;


// Make sure important select fields are not default/unknown values
const meaningfulSelects =
  leadData.maritalStatus !== 'Unknown' &&
  leadData.mortgageStatus !== 'Unknown' &&
  leadData.propertyType !== 'Other';


// Lead is complete only if:
// 1. AI says leadComplete = true
// 2. all required text fields are complete
// 3. number fields are complete
// 4. select fields have meaningful values
const leadComplete =
  Boolean(parsed?.leadComplete) &&
  textFieldsComplete &&
  numberFieldsComplete &&
  meaningfulSelects;


// Send clean data to the next n8n nodes
return [{
  json: {
    replyText: parsed?.replyText || raw || 'Danke für Ihre Nachricht.',
    leadComplete,

    // Needed if we update an existing Airtable record
    airtableRecordId: existing.recordId || '',

    // Shows if this customer already exists in Airtable
    customerExists: ctx.customerExists || false,

    // Final cleaned lead data
    ...leadData,
  },
}];

// Get the current WhatsApp message data from the "Data" node
const incoming = $('Data').item.json;

// Get the Airtable record.
// If no Airtable record was found, use an empty object.
const record = $json || {};


// Helper function:
// Take the first value that is not empty.
function pick(...values) {
  for (const value of values) {
    if (value !== undefined && value !== null && String(value).trim() !== '') {
      return value;
    }
  }
  return '';
}


// Helper function:
// Convert values like "2.000 €" or "2000" into a real number.
function toNumber(value) {
  if (value === null || value === undefined || value === '') return 0;

  return Number(
    String(value)
      .replace(/[^\d,.-]/g, '') // remove currency symbols and text
      .replace(',', '.')        // convert comma to dot
  ) || 0;
}


// Helper function:
// Check if a field already has a useful value.
function isFilled(value, field) {

  // These fields must be bigger than 0
  if (field === 'age' || field === 'netSalary' || field === 'budget') {
    return toNumber(value) > 0;
  }

  // Number of children can be 0, so empty check is enough
  if (field === 'numberChildren') {
    return value !== undefined && value !== null && String(value).trim() !== '';
  }

  // These fields should not stay as default values
  if (
    field === 'maritalStatus' ||
    field === 'timeline' ||
    field === 'mortgageStatus' ||
    field === 'propertyType'
  ) {
    const v = String(value || '').trim();

    return (
      v !== '' &&
      v !== 'Unknown' &&
      !(field === 'timeline' && v === 'Just exploring') &&
      !(field === 'propertyType' && v === 'Other')
    );
  }

  // For normal text fields, check if text exists
  return String(value || '').trim() !== '';
}


// Check if Airtable already returned an existing customer
const customerExists = Boolean(
  record.id ||
  record.Phone ||
  record.Email ||
  record['Full Name'] ||
  record['First Name'] ||
  record.Name
);


// Build one clean customer object for the AI Agent
const existingData = {
  // Airtable record ID, needed later for updating existing records
  recordId: record.id || '',

  // Use Airtable phone if available, otherwise use WhatsApp sender ID
  phone: pick(record.Phone, incoming.from),

  // New fields
  fullName: pick(record['Full Name'], record.Name),
  email: pick(record.Email),

  // Existing fields
  firstName: pick(record['First Name']),
  nationality: pick(record.Nationality),
  age: toNumber(record.Age),
  maritalStatus: pick(record['Marital Status']),
  numberChildren: record['Number of Children'] ?? '',
  netSalary: toNumber(record['Net Salary']),
  budget: toNumber(record.Budget),
  timeline: pick(record.Timeline),
  mortgageStatus: pick(record['Mortgage Status']),
  propertyType: pick(record['Property Type']),
  preferredAreas: pick(record['Preferred Areas']),
  qualifiedLead: record['Qualified Lead'] === true,
};


// This is the order in which the AI should ask questions
const fieldOrder = [
  'fullName',
  'firstName',
  'email',
  'nationality',
  'age',
  'maritalStatus',
  'numberChildren',
  'netSalary',
  'budget',
  'timeline',
  'mortgageStatus',
  'propertyType',
  'preferredAreas'
];


// Create a list of fields that are still missing
const missingFields = fieldOrder.filter((field) => {
  return !isFilled(existingData[field], field);
});


// Send the prepared context to the AI Agent
return [{
  json: {
    // What the user just wrote on WhatsApp
    userMessage: incoming.body || '',

    // WhatsApp ID of the customer
    phone: incoming.from || '',

    // WAHA session
    session: incoming.session || 'default',

    // WhatsApp display name, if available
    notifyName: incoming.notifyName || '',

    // True if customer already exists in Airtable
    customerExists,

    // All known customer data
    existingData,

    // All fields still missing
    missingFields,

    // The next field the AI should ask about
    firstMissingField: missingFields[0] || '',
  }
}];
